:root {
            --navy: #0a2145;
            --navy-2: #10366f;
            --blue: #1767d9;
            --sky: #e9f2ff;
            --orange: #f47a31;
            --orange-dark: #df5d15;
            --ink: #14233c;
            --muted: #66758b;
            --line: #dce4ef;
            --surface: #ffffff;
            --soft: #f5f8fc;
        }

        * { box-sizing: border-box; }
        html { scroll-behavior: smooth; }
        body {
            margin: 0;
            background: var(--surface);
            color: var(--ink);
            font-family: "Pretendard Variable", Pretendard, "Noto Sans KR", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
            -webkit-font-smoothing: antialiased;
        }
        a { color: inherit; text-decoration: none; }
        button, input, select, textarea { font: inherit; }
        button { cursor: pointer; }
        section[id] { scroll-margin-top: 96px; }
        h1, h2, h3, p { word-break: keep-all; overflow-wrap: break-word; }

        .site-header {
            position: sticky;
            top: 0;
            z-index: 80;
            height: 76px;
            background: rgba(255,255,255,.96);
            border-bottom: 1px solid rgba(220,228,239,.9);
        }
        .header-inner {
            max-width: 1480px;
            height: 100%;
            margin: 0 auto;
            padding: 0 36px;
            display: flex;
            align-items: center;
            gap: 44px;
        }
        .brand { display: inline-flex; align-items: center; gap: 11px; font-size: 20px; font-weight: 900; letter-spacing: -.055em; white-space: nowrap; }
        .brand > span:last-child { display: flex; align-items: baseline; gap: 5px; }
        .brand small { font-size: 14px; color: #617089; font-weight: 700; letter-spacing: -.02em; }
        .brand-symbol { position: relative; display: inline-block; width: 30px; height: 30px; transform: rotate(-8deg); }
        .brand-symbol b { position: absolute; display: block; width: 9px; border-radius: 10px; background: var(--orange); }
        .brand-symbol b:nth-child(1) { height: 19px; left: 2px; top: 8px; }
        .brand-symbol b:nth-child(2) { height: 27px; left: 11px; top: 2px; background: #f18c24; }
        .brand-symbol b:nth-child(3) { height: 16px; left: 20px; top: 11px; background: #ff9d4f; }
        nav { display: flex; gap: 30px; margin-right: auto; }
        nav a { font-size: 14px; font-weight: 700; color: #47566d; transition: color .2s; }
        nav a:hover { color: var(--blue); }
        .header-actions { display: flex; align-items: center; gap: 18px; }
        .text-link { font-size: 16px; font-weight: 700; color: #5b6a80; }
        .header-cta { padding: 12px 18px; border-radius: 8px; background: var(--navy); color: white; font-size: 16px; font-weight: 800; }

        .page-shell { max-width: 1480px; margin: 0 auto; padding: 28px 36px 80px; display: grid; grid-template-columns: minmax(0, 1fr) 356px; gap: 28px; align-items: start; }
        .content-column { min-width: 0; }
        .hero-section { min-height: 650px; position: relative; overflow: hidden; border-radius: 28px; padding: 72px 6.5%; background: linear-gradient(132deg, #071b39 0%, #0c2d60 57%, #124786 100%); color: white; display: grid; grid-template-columns: 1.05fr .95fr; align-items: center; isolation: isolate; }
        .hero-section::before { content: ""; position: absolute; inset: 0; z-index: -2; opacity: .16; background-image: linear-gradient(rgba(255,255,255,.14) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.14) 1px, transparent 1px); background-size: 42px 42px; mask-image: linear-gradient(110deg, transparent, #000 58%, #000); }
        .hero-glow { position: absolute; border-radius: 50%; filter: blur(2px); z-index: -1; }
        .glow-one { width: 470px; height: 470px; right: -140px; top: -180px; background: radial-gradient(circle, rgba(61,156,255,.45), transparent 70%); }
        .glow-two { width: 340px; height: 340px; left: 32%; bottom: -250px; background: radial-gradient(circle, rgba(244,122,49,.24), transparent 70%); }
        .hero-copy { position: relative; z-index: 2; min-width: 0; }
        .ministry-badge { width: min(100%, 410px); margin-bottom: 25px; padding: 10px 14px; border: 1px solid rgba(255,255,255,.18); border-radius: 10px; background: rgba(255,255,255,.96); box-shadow: 0 10px 24px rgba(0,0,0,.12); }
        .ministry-badge img { width: 100%; height: auto; display: block; }
        .hero-copy h1 { margin: 0; font-size: clamp(42px, 4.4vw, 64px); line-height: 1.2; letter-spacing: -.045em; font-weight: 850; word-break: keep-all; overflow-wrap: break-word; }
        .hero-copy h1 em { font-style: normal; color: #ff5a45; }
        .hero-lead { max-width: 560px; margin: 28px 0 0; color: #d4e3f6; font-size: 17px; line-height: 1.8; word-break: keep-all; }
        .hero-buttons { margin-top: 34px; display: flex; gap: 12px; flex-wrap: wrap; }
        .primary-button, .secondary-button { min-height: 52px; padding: 0 22px; display: inline-flex; align-items: center; justify-content: center; border-radius: 9px; font-size: 15px; font-weight: 800; transition: transform .2s, background .2s; }
        .primary-button { background: var(--orange); color: white; box-shadow: 0 12px 26px rgba(244,122,49,.24); }
        .primary-button:hover { background: var(--orange-dark); transform: translateY(-2px); }
        .primary-button span { margin-left: 22px; font-size: 20px; }
        .secondary-button { color: white; border: 1px solid rgba(255,255,255,.32); background: rgba(255,255,255,.05); }
        .secondary-button:hover { background: rgba(255,255,255,.12); }
        .hero-points { margin-top: 38px; display: flex; gap: 9px; flex-wrap: wrap; color: #e0ecfa; }
        .hero-points > span { min-height: 38px; padding: 8px 11px; display: inline-flex; align-items: center; gap: 7px; border: 1px solid rgba(255,255,255,.15); border-radius: 8px; background: rgba(255,255,255,.07); }
        .hero-points i { color: #78b6ff; font-style: normal; font-size: 12px; font-weight: 900; letter-spacing: .06em; }
        .hero-points b { font-size: 14px; font-weight: 750; }

        .hero-visual { position: relative; height: 470px; display: flex; align-items: center; justify-content: center; min-width: 0; overflow: visible; }
        .dashboard-card { width: min(100%, 270px); margin: 0 auto; padding: 26px; border: 1px solid rgba(255,255,255,.22); border-radius: 24px; background: rgba(255,255,255,.96); color: var(--ink); box-shadow: 0 28px 70px rgba(0,0,0,.3); transform: rotate(1.2deg); }
        .dashboard-head { display: flex; justify-content: space-between; align-items: center; }
        .dashboard-head div { display: flex; align-items: center; gap: 8px; }
        .dashboard-head strong { font-size: 14px; }
        .dashboard-head small { color: #8390a3; font-size: 14px; }
        .mini-mark { width: 10px; height: 10px; border-radius: 3px; background: var(--orange); box-shadow: 5px -4px 0 #1a75e8; transform: rotate(-8deg); }
        .progress-ring { width: 126px; height: 126px; margin: 30px auto 10px; border-radius: 50%; display: grid; place-items: center; background: conic-gradient(var(--blue) 0 98%, #e8edf4 98%); position: relative; }
        .progress-ring::after { content: ""; position: absolute; inset: 13px; border-radius: 50%; background: white; }
        .progress-ring span { position: relative; z-index: 1; font-size: 32px; font-weight: 850; letter-spacing: -.04em; }
        .progress-ring small { font-size: 15px; }
        .dashboard-card > p { margin: 0 0 24px; text-align: center; color: #78869a; font-size: 14px; }
        .bar-list { display: grid; gap: 14px; }
        .bar-list > div { display: grid; grid-template-columns: 74px 1fr 32px; gap: 10px; align-items: center; font-size: 14px; }
        .bar-list span { color: #637188; }
        .bar-list b { height: 7px; overflow: hidden; border-radius: 10px; background: #e7edf5; }
        .bar-list i { height: 100%; display: block; border-radius: inherit; background: linear-gradient(90deg, #1b67d4, #59a0f5); }
        .bar-list em { color: var(--blue); font-style: normal; font-weight: 800; }
        .floating-card { position: absolute; padding: 12px 15px; display: flex; gap: 10px; align-items: center; border: 1px solid rgba(255,255,255,.65); border-radius: 14px; background: rgba(255,255,255,.96); color: var(--ink); box-shadow: 0 16px 35px rgba(1,20,51,.28); }
        .floating-card > span { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; background: #e9f5ee; color: #258357; font-weight: 900; font-size: 16px; }
        .floating-card div { display: grid; gap: 2px; }
        .floating-card b { font-size: 14px; }
        .floating-card small { font-size: 13px; color: #8490a2; }
        .card-a { right: 0; top: 54px; }
        .card-b { left: 0; bottom: 56px; }
        .card-b > span { background: #fff1e8; color: var(--orange); }

        .trust-strip { display: grid; grid-template-columns: repeat(3, 1fr); margin: 22px 0 0; border: 1px solid var(--line); border-radius: 18px; background: white; box-shadow: 0 12px 35px rgba(26,54,94,.06); }
        .trust-strip > div { min-height: 112px; padding: 23px 26px; display: grid; grid-template-columns: 46px 1fr; grid-template-rows: auto auto; column-gap: 13px; align-content: center; border-right: 1px solid var(--line); }
        .trust-strip > div:last-child { border-right: 0; }
        .trust-strip span { grid-row: 1 / 3; width: 42px; height: 42px; display: grid; place-items: center; border-radius: 12px; background: #edf5ff; color: var(--blue); font-size: 18px; font-weight: 850; }
        .trust-strip b { font-size: 14px; }
        .trust-strip small { margin-top: 5px; color: var(--muted); font-size: 14px; line-height: 1.45; }

        .fact-section { margin-top: 22px; padding: 72px 7%; border-radius: 24px; background: var(--soft); display: grid; grid-template-columns: .75fr 1.25fr; gap: 54px; align-items: center; }
        .section-label { width: fit-content; min-height: 27px; margin: 0 0 17px; padding: 0 10px; display: inline-flex; align-items: center; border-radius: 5px; background: #edf4fd; color: var(--blue); font-size: 13px; font-weight: 900; letter-spacing: .14em; }
        .section-heading h2 { margin: 0; font-size: 44px; line-height: 1.28; letter-spacing: -.04em; }
        .section-heading > p:last-child { margin: 18px 0 0; color: var(--muted); font-size: 16px; line-height: 1.7; }
        .fact-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
        .fact-grid article { min-height: 158px; padding: 22px 24px; border-radius: 16px; background: white; border: 1px solid #e0e8f2; display: flex; flex-direction: column; justify-content: center; box-shadow: 0 8px 24px rgba(16,50,92,.035); }
        .fact-grid strong { color: var(--navy); font-size: 30px; letter-spacing: -.035em; }
        .fact-grid strong > span { display: inline-block; margin: 0; color: inherit; font-size: inherit; font-variant-numeric: tabular-nums; }
        .fact-grid strong small { margin-left: 4px; color: var(--blue); font-size: 15px; }
        .fact-grid span { margin-top: 8px; color: var(--muted); font-size: 14px; }
        .fact-grid .fact-label { width: fit-content; margin: 0 0 12px; padding: 6px 9px; border-radius: 6px; background: var(--navy); color: white; font-size: 13px; font-weight: 800; }
        .program-section { padding: 82px 6%; }
        .section-heading.centered { max-width: 760px; margin: 0 auto 46px; text-align: center; }
        .section-heading.centered .section-label { margin-left: auto; margin-right: auto; justify-content: center; }
        .section-heading h2 em { color: var(--blue); font-style: normal; }
        .program-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
        .program-card { position: relative; min-height: 318px; padding: 22px; overflow: hidden; border: 1px solid var(--line); border-radius: 17px; background: white; transition: transform .2s, border-color .2s, box-shadow .2s; }
        .program-card { transition: transform .35s cubic-bezier(.2,.8,.2,1), border-color .3s, box-shadow .35s; }
        .program-card:hover { transform: translateY(-10px) scale(1.02); border-color: #8fb6ee; box-shadow: 0 26px 46px rgba(22,61,111,.16); }
        .program-number { position: absolute; right: 18px; top: 17px; color: #8da2bb; font-size: 14px; font-weight: 850; letter-spacing: .12em; }
        .program-illustration { width: 104px; height: 104px; margin: 0 0 18px; border-radius: 16px; background-image: url('data:image/png;base64,'); background-repeat: no-repeat; background-size: 300% 200%; box-shadow: inset 0 0 0 1px #e1eaf5; }
        .illustration-01 { background-position: 0 0; }
        .illustration-02 { background-position: 50% 0; }
        .illustration-03 { background-position: 100% 0; }
        .illustration-04 { background-position: 0 100%; }
        .illustration-05 { background-position: 50% 100%; }
        .illustration-06 { background-position: 100% 100%; }
        .program-card h3 { min-height: 48px; margin: 0; font-size: 17px; line-height: 1.45; letter-spacing: -.03em; }
        .program-card p { margin: 10px 0 14px; color: var(--muted); font-size: 14px; line-height: 1.6; }
        .program-card small { display: inline-block; padding: 6px 8px; border-radius: 6px; background: #fff3eb; color: #cf5b1d; font-size: 13px; font-weight: 750; }
        .reporting-row { margin-top: 16px; padding: 24px; display: grid; grid-template-columns: 220px 1fr; align-items: center; gap: 16px 28px; border-radius: 16px; background: var(--navy); color: white; }
        .reporting-title { min-width: 195px; display: flex; align-items: center; gap: 12px; }
        .reporting-title > span { width: 52px; height: 52px; display: grid; place-items: center; border-radius: 13px; background: rgba(255,255,255,.1); font-size: 24px; }
        .reporting-title div { display: grid; gap: 3px; }
        .reporting-title b { font-size: 16px; }
        .reporting-title small { color: #9fb3cf; font-size: 13px; }
        .reporting-tags { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
        .reporting-tags span { min-height: 36px; padding: 8px 10px; display: flex; align-items: center; border-radius: 7px; background: rgba(255,255,255,.09); color: #e3edf9; font-size: 13px; }
        .legal-note { grid-column: 1 / -1; margin: 0; padding-top: 3px; color: #b8cae0; font-size: 13px; line-height: 1.6; }

        .safety-section { position: relative; margin: 0; padding: 70px 6% 42px; overflow: hidden; border-radius: 25px; background: linear-gradient(135deg, #0b2348, #123e7f); color: white; display: grid; grid-template-columns: .8fr 1.2fr; gap: 42px; align-items: center; }
        .safety-section::after { content: ""; position: absolute; width: 430px; height: 430px; right: -240px; bottom: -280px; border-radius: 50%; border: 70px solid rgba(255,255,255,.04); }
        .section-label.light { background: rgba(255,255,255,.1); color: #9bc8ff; }
        .safety-copy h2 { margin: 0; font-size: 35px; line-height: 1.3; letter-spacing: -.045em; }
        .safety-copy > p:nth-of-type(2) { margin: 18px 0 0; color: #b9cae0; font-size: 15px; line-height: 1.7; }
        .industry-chips { margin-top: 25px; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
        .industry-chips span { min-height: 38px; padding: 8px 10px; display: flex; align-items: center; border: 1px solid rgba(255,255,255,.2); border-radius: 9px; background: rgba(255,255,255,.07); color: #edf5ff; font-size: 14px; font-weight: 750; }
        .safety-cards { position: relative; z-index: 1; display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
        .safety-cards article { min-height: 270px; padding: 25px; border: 1px solid rgba(255,255,255,.17); border-radius: 17px; background: rgba(255,255,255,.1); display: flex; flex-direction: column; }
        .safety-cards article > span { display: inline-block; padding: 6px 8px; border-radius: 6px; background: rgba(130,183,255,.16); color: #97c6ff; font-size: 13px; font-weight: 800; }
        .safety-cards h3 { margin: 18px 0 13px; font-size: 18px; line-height: 1.45; }
        .safety-cards p { margin: 0; min-height: 52px; color: #b9c9df; font-size: 14px; line-height: 1.7; }
        .safety-cards b { display: block; margin-top: auto; padding-top: 22px; color: #ff9a58; font-size: 15px; }
        .safety-note { grid-column: 1 / -1; margin: 2px 0 0; color: #8fa7c7; font-size: 12px; }

        .industry-section { padding: 82px 6%; }
        .industry-tabs { margin: -12px auto 26px; display: flex; justify-content: center; gap: 7px; flex-wrap: wrap; }
        .industry-tabs button { min-width: 105px; min-height: 42px; padding: 0 17px; border: 1px solid var(--line); border-radius: 9px; background: white; color: #6f7d90; font-size: 15px; font-weight: 750; }
        .industry-tabs button.active { border-color: var(--navy); background: var(--navy); color: white; box-shadow: 0 10px 20px rgba(10,33,69,.12); }
        .industry-detail { min-height: 355px; padding: 44px; border: 1px solid #dce5f0; border-radius: 22px; background: #f6f9fd; display: grid; grid-template-columns: .85fr 1.15fr; gap: 46px; align-items: center; }
        .industry-intro > p { margin: 0 0 13px; color: var(--blue); font-size: 14px; font-weight: 850; letter-spacing: .13em; }
        .industry-intro h3 { margin: 0; font-size: 29px; letter-spacing: -.045em; }
        .industry-intro > span { display: block; margin-top: 14px; color: var(--muted); font-size: 15px; line-height: 1.65; }
        .industry-intro a { margin-top: 30px; display: inline-flex; align-items: center; gap: 35px; color: var(--navy); font-size: 15px; font-weight: 850; }
        .industry-intro a b { color: var(--orange); font-size: 18px; }
        .industry-programs { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }
        .industry-programs > div { min-height: 58px; padding: 0 14px; display: grid; grid-template-columns: 26px 1fr 18px; align-items: center; gap: 8px; border: 1px solid #e1e8f1; border-radius: 10px; background: white; }
        .industry-programs > div span { color: #9aa8ba; font-size: 13px; font-weight: 800; }
        .industry-programs > div b { font-size: 14px; line-height: 1.4; }
        .industry-programs > div i { width: 18px; height: 18px; display: grid; place-items: center; border-radius: 50%; background: #eaf4ff; color: var(--blue); font-style: normal; font-size: 13px; }
        .industry-programs > p { grid-column: 1 / -1; margin: 5px 0 0; color: #7b899c; font-size: 13px; }

        .why-section { padding: 80px 6%; border-radius: 24px; background: #f5f8fc; }
        .why-section > .section-heading { max-width: 540px; margin-bottom: 36px; }
        .why-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
        .why-grid article { min-height: 230px; padding: 24px; border: 1px solid #e1e8f1; border-radius: 16px; background: white; }
        .why-grid span { display: block; color: var(--orange); font-size: 14px; font-weight: 850; }
        .why-grid h3 { margin: 55px 0 12px; font-size: 15px; letter-spacing: -.025em; }
        .why-grid p { margin: 0; color: var(--muted); font-size: 14px; line-height: 1.7; word-break: keep-all; }

        .process-section { padding: 84px 4%; }
        .process-list { position: relative; display: grid; grid-template-columns: repeat(7, 1fr); gap: 9px; }
        .process-list article { position: relative; z-index: 1; text-align: center; }
        .process-list article:not(:last-child)::after { content: "→"; position: absolute; right: -11px; top: 20px; z-index: 2; color: #9bb0c9; font-size: 18px; font-weight: 700; }
        .process-list article > span { width: 54px; height: 54px; margin: 0 auto 8px; display: grid; place-items: center; border: 1px solid #d8e4f1; border-radius: 16px; background: #edf5ff; font-size: 24px; box-shadow: 0 6px 16px rgba(17,54,99,.06); }
        .process-list article > small { display: block; margin-bottom: 10px; color: var(--blue); font-size: 12px; font-weight: 900; letter-spacing: .08em; }
        .process-list h3 { margin: 0; font-size: 15px; }
        .process-list p { margin: 6px 0 0; color: var(--muted); font-size: 13px; line-height: 1.4; }
        .process-tip { max-width: 620px; margin: 38px auto 0; padding: 14px 18px; display: flex; justify-content: center; gap: 15px; border-radius: 9px; background: #edf5ff; font-size: 14px; }
        .process-tip b { color: var(--blue); }
        .process-tip span { color: #607188; }

        .faq-section { padding: 72px 7%; border: 1px solid var(--line); border-radius: 24px; }
        .faq-section > .section-heading { margin-bottom: 34px; }
        .faq-list { max-width: 860px; margin: 0 auto; }
        .faq-list details { border-bottom: 1px solid var(--line); }
        .faq-list details:first-child { border-top: 1px solid var(--line); }
        .faq-list summary { min-height: 70px; padding: 0 4px; display: grid; grid-template-columns: 27px 1fr 20px; align-items: center; gap: 10px; list-style: none; cursor: pointer; font-size: 15px; font-weight: 780; }
        .faq-list summary::-webkit-details-marker { display: none; }
        .faq-list summary > span { color: var(--orange); font-size: 15px; font-weight: 900; }
        .faq-list summary i { position: relative; width: 16px; height: 16px; }
        .faq-list summary i::before, .faq-list summary i::after { content: ""; position: absolute; left: 2px; right: 2px; top: 7px; height: 1px; background: #718096; transition: transform .2s; }
        .faq-list summary i::after { transform: rotate(90deg); }
        .faq-list details[open] summary i::after { transform: rotate(0); }
        .faq-list details p { margin: -2px 0 18px; padding: 0 30px 0 41px; color: var(--muted); font-size: 14px; line-height: 1.75; }

        .closing-section { margin: 22px 0 0; padding: 58px 7%; border-radius: 24px; background: linear-gradient(135deg, #0a2043, #154d91); color: white; display: grid; grid-template-columns: minmax(0, 1fr) 210px; gap: 52px; align-items: center; }
        .closing-section h2 { margin: 0; font-size: 35px; line-height: 1.28; letter-spacing: -.045em; }
        .closing-section > div > p:last-child { margin: 15px 0 0; color: #b9cae0; font-size: 14px; line-height: 1.65; }
        .closing-actions { width: 100%; display: grid; gap: 9px; }
        .closing-actions a { min-height: 48px; padding: 0 17px; display: flex; align-items: center; justify-content: space-between; border-radius: 8px; font-size: 15px; font-weight: 800; }
        .closing-actions a:first-child { background: var(--orange); }
        .closing-actions a:last-child { justify-content: center; border: 1px solid rgba(255,255,255,.25); color: #dbe7f6; }

        .site-footer { margin-top: 20px; padding: 58px 36px 24px; background: #07172f; color: white; }
        .footer-inner { max-width: 1410px; margin: 0 auto; display: grid; grid-template-columns: .7fr 1.3fr .7fr; gap: 60px; }
        .footer-brand .brand small { color: #7f91aa; }
        .footer-brand > p { margin: 20px 0 0; color: #8292a8; font-size: 14px; line-height: 1.7; }
        .footer-info { display: grid; grid-template-columns: 1.4fr .6fr; gap: 35px; }
